       COUNT(*) FILTER (WHERE d.arquivado_em IS NULL) AS ainda_ativos,
       COUNT(*) FILTER (WHERE m.arquivado_em IS NULL AND m.item = d.item) AS manter_ok
FROM p JOIN prestadores d ON d.id=p.id_arquivar JOIN prestadores m ON m.id=p.id_manter;

